# Let me manually trace through the patterns
inputs = ['fchwby', 'xe', 'ud', 'ivydfd', 'guwa']
outputs = ['fchkvubfz', 'xe', 'ud', 'aacedfd', 'gukvua']

print("Input -> Output:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"{inp} -> {out}")

# Let's see character by character differences
print("\nDetailed analysis:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"\n{inp} -> {out}")
    # Create mapping of what changed
    j = 0
    while j < max(len(inp), len(out)):
        if j < len(inp) and j < len(out):
            if inp[j] != out[j]:
                print(f"  Position {j}: '{inp[j]}' -> '{out[j]}'")
        elif j < len(inp):
            print(f"  Position {j}: '{inp[j]}' (removed)")
        elif j < len(out):
            print(f"  Position {j}: '{out[j]}' (added)")
        j += 1

